-- Name: get_user_ranking(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_ranking(p_limit integer DEFAULT 100) RETURNS TABLE(user_id uuid, username text, avatar_url text, personal_shards bigint, profile_public boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT
        u.id,
        u.username,
        u.avatar_url,
        u.personal_shards::bigint,
        u.profile_public
    FROM public.users u
    WHERE u.deleted_at IS NULL
    ORDER BY u.personal_shards DESC, u.username ASC
    LIMIT p_limit;
$$;


